changeSet.sql:
CREATE MATERIALIZED VIEW mv_daily_recon_summary AS SELECT t.trade_date, c.region, t.asset_class, COUNT(*) AS total_trades, COUNT(*) FILTER (WHERE status = 'MATCHED') AS matched_trades, COUNT(*) FILTER (WHERE status IN ('UNMATCHED','DISPUTED')) AS break_trades, COALESCE(SUM(quantity * price), 0) AS total_notional FROM trades t LEFT JOIN recon_breaks rb ON rb.trade_id = t.id AND rb.trade_date = t.trade_date INNER JOIN counterparties c ON c.id = t.counterparty_id
WHERE deleted_at IS NULL GROUP BY t.trade_date, c.region, t.asset_class;
CREATE UNIQUE INDEX uq_mv_daily_recon_summary_trade_date ON mv_daily_recon_summary (trade_date, region, asset_class);
